// The one market report (docs/open-decisions.md, 2026-10-18): always the accurate picture of the member's
// hireability as of now, regenerated by the member after they have made improvements. Pure rules, client-safe,
// so the redesigned page, the regenerate action and the tests all read the same decisions.
//
// No letter grade, no verdict label. Every line is a fact on file plus, where it helps, the next thing to do.

import type { HiringReason, HiringStatus } from './hiring-case'
import type { LaunchStep } from './launchpad'
import type { Objection } from './evaluators'

// ── Regenerating ───────────────────────────────────────────────────────────

/** At least this long between two refreshes (each one is a model call). */
export const REGEN_COOLDOWN_MINUTES = 30
/** And never more than this many in a rolling day. */
export const REGEN_MAX_PER_DAY = 3

export type RegenReason = 'first_report' | 'resume_updated' | 'search_details_updated' | 'applied_to_jobs' | 'references_added'

export interface ImprovementSignals {
  /** When the newest resume was uploaded. */
  resumeUploadedAt: Date | null
  /** When the member last confirmed their search details. */
  searchStrategyConfirmedAt: Date | null
  /** Applications logged since the last report. */
  applicationsSince: number
  /** References completed since the last report. */
  referencesSince: number
}

/** What the member has done since the last report was generated. Empty means nothing new to read. */
export function improvementReasons(lastGeneratedAt: Date | null, s: ImprovementSignals): RegenReason[] {
  if (!lastGeneratedAt) return ['first_report']
  const out: RegenReason[] = []
  if (s.resumeUploadedAt && s.resumeUploadedAt > lastGeneratedAt) out.push('resume_updated')
  if (s.searchStrategyConfirmedAt && s.searchStrategyConfirmedAt > lastGeneratedAt) out.push('search_details_updated')
  if (s.applicationsSince > 0) out.push('applied_to_jobs')
  if (s.referencesSince > 0) out.push('references_added')
  return out
}

export const REGEN_REASON_TEXT: Record<RegenReason, string> = {
  first_report: 'You have not generated a report yet.',
  resume_updated: 'you updated your resume',
  search_details_updated: 'you updated your search details',
  applied_to_jobs: 'you applied to jobs',
  references_added: 'you completed references',
}

export type RegenBlock = 'nothing_new' | 'too_soon' | 'daily_limit'

export interface RegenDecision {
  allowed: boolean
  blockedBy: RegenBlock | null
  reasons: RegenReason[]
  /** The single reason recorded with the event: the first one found. */
  reason: RegenReason | null
  /** When it opens up again, for the two time-based limits. */
  availableAt: Date | null
  /** Plain words for the member: what is ready, or why not and what to do. */
  message: string
}

export function regenerationDecision(input: {
  now: Date
  lastGeneratedAt: Date | null
  /** Reports generated in the 24 hours before now. */
  generatedLast24h: number
  /** Time of the oldest of those, to say when the daily limit lifts. */
  oldestOfLast24h?: Date | null
  signals: ImprovementSignals
}): RegenDecision {
  const reasons = improvementReasons(input.lastGeneratedAt, input.signals)
  const reason = reasons[0] ?? null
  if (!input.lastGeneratedAt) {
    return { allowed: true, blockedBy: null, reasons, reason, availableAt: null, message: 'Your first report is ready to generate.' }
  }
  if (reasons.length === 0) {
    return {
      allowed: false,
      blockedBy: 'nothing_new',
      reasons,
      reason,
      availableAt: null,
      message: 'This report already reflects everything on file. Update your resume, your search details or your references, then regenerate.',
    }
  }
  const cooldownEnds = new Date(input.lastGeneratedAt.getTime() + REGEN_COOLDOWN_MINUTES * 60_000)
  if (cooldownEnds > input.now) {
    return {
      allowed: false,
      blockedBy: 'too_soon',
      reasons,
      reason,
      availableAt: cooldownEnds,
      message: `You refreshed this a moment ago. You can regenerate again in ${minutesUntil(cooldownEnds, input.now)}.`,
    }
  }
  if (input.generatedLast24h >= REGEN_MAX_PER_DAY) {
    const opens = new Date((input.oldestOfLast24h ?? input.lastGeneratedAt).getTime() + 24 * 3_600_000)
    return {
      allowed: false,
      blockedBy: 'daily_limit',
      reasons,
      reason,
      availableAt: opens,
      message: `You have refreshed this ${REGEN_MAX_PER_DAY} times today. It opens again ${opens > input.now ? `in ${minutesUntil(opens, input.now)}` : 'now'}.`,
    }
  }
  return { allowed: true, blockedBy: null, reasons, reason, availableAt: null, message: `Ready to refresh, because ${joinReasons(reasons)}.` }
}

function minutesUntil(at: Date, now: Date): string {
  const mins = Math.max(1, Math.ceil((at.getTime() - now.getTime()) / 60_000))
  if (mins < 60) return `${mins} minute${mins === 1 ? '' : 's'}`
  const hours = Math.ceil(mins / 60)
  return `${hours} hour${hours === 1 ? '' : 's'}`
}

function joinReasons(reasons: RegenReason[]): string {
  const texts = reasons.filter((r) => r !== 'first_report').map((r) => REGEN_REASON_TEXT[r])
  if (texts.length <= 1) return texts[0] ?? 'there is something new to read'
  return `${texts.slice(0, -1).join(', ')} and ${texts[texts.length - 1]}`
}

// ── Reading the report ─────────────────────────────────────────────────────

/** Wording for each state: what is true now, said in the direction of the next step. */
export const POSITIVE_STATUS: Record<HiringStatus, string> = {
  in_place: 'In place',
  issue: 'Ready to improve',
  missing: 'Next to build',
  unknown: 'Answer to count it',
}

export interface CurrentReadInput {
  hiringCase: HiringReason[]
  market: { openRoles: number; targetLabel: string; trend: string | null } | null
  launchpad: LaunchStep[]
  objections: Objection[]
}

export interface ReadRow {
  key: string
  title: string
  /** The fact it rests on. */
  fact: string
  status: string
  next: string | null
  tool: string | null
  href: string | null
}

export interface CurrentRead {
  headline: string
  /** What the headline rests on, in one line. */
  because: string
  inPlace: ReadRow[]
  toBuild: ReadRow[]
  market: { line: string; fact: string } | null
  /** The first twelve weeks: not yet done, in order. */
  steps: LaunchStep[]
  doneSteps: number
  questions: { question: string; answer: string }[]
}

const sentence = (s: string) => s.charAt(0).toUpperCase() + s.slice(1)

function rowOf(r: HiringReason): ReadRow {
  return {
    key: r.key,
    title: sentence(r.reason.replace(/^who /i, '')),
    fact: r.seen,
    status: POSITIVE_STATUS[r.status],
    next: r.status === 'in_place' ? null : r.next,
    tool: r.status === 'in_place' ? null : r.tool,
    href: r.status === 'in_place' ? null : r.href,
  }
}

export function buildCurrentRead(i: CurrentReadInput): CurrentRead {
  const total = i.hiringCase.length
  const placed = i.hiringCase.filter((r) => r.status === 'in_place')
  const open = i.hiringCase.filter((r) => r.status !== 'in_place')
  const readable = i.hiringCase.filter((r) => r.status !== 'unknown').length

  let headline: string
  let because: string
  if (total === 0) {
    headline = 'Your report fills in as you add to your profile.'
    because = 'There is not enough on file yet to read. A resume and your search details are the quickest start.'
  } else if (placed.length === 0) {
    headline = `Your report starts here: ${total} things employers hire for are waiting to be counted.`
    because = `${readable} of ${total} can be read from what is on file now. Each answer you give or tool you use adds to it.`
  } else {
    headline = `${placed.length} of the ${total} things employers hire for are already in place.`
    because = `Read from your resume, search details, references and activity as of today. ${open.length > 0 ? `${open.length} more can be added inside NextChapter.` : 'Everything we can read is in place.'}`
  }

  const marketLine = i.market
    ? {
        line: `${i.market.openRoles.toLocaleString()} open roles fit ${i.market.targetLabel}${i.market.trend ? `, and the market is ${i.market.trend}` : ''}.`,
        fact: 'Counted on level, field, place and skills from the live NextChapter job board.',
      }
    : null

  const todo = i.launchpad.filter((s) => !s.done)
  return {
    headline,
    because,
    inPlace: placed.map(rowOf),
    toBuild: open.map(rowOf),
    market: marketLine,
    steps: todo,
    doneSteps: i.launchpad.length - todo.length,
    questions: [...i.objections]
      .sort((a, b) => b.severity - a.severity)
      .slice(0, 3)
      .map((o) => ({ question: o.question, answer: o.answer })),
  }
}
